import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("remove.txt"); Files.writeString(path, "temporary"); Files.delete(path); System.out.println(Files.exists(path)); } }

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("optional.txt"); System.out.println(Files.deleteIfExists(path)); } }

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path folder = Path.of("empty-folder"); Files.createDirectory(folder); Files.delete(folder); System.out.println(Files.exists(folder)); } }

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
public class Main { public static void main(String[] args) throws IOException { Path path = Path.of("confirm.txt"); Files.writeString(path, "data"); boolean removed = Files.deleteIfExists(path); System.out.println(removed); System.out.println(Files.exists(path)); } }
